INSERT INTO bike_stock_out_batch(batch_no,series_id,execution_pi_id,customer_id,request_id,payload_hash,source_type,operator_id)
    SELECT #{batchNo},p.series_id,p.id,p.customer_id,#{requestId},#{hash},#{type},#{operatorId}
    FROM bike_pi p JOIN bike_pi_series s ON s.id=p.series_id AND s.current_pi_id=p.id WHERE p.id=#{piId}
